import { useState, useEffect } from "react";
import { useLocale } from "../context/LocaleContext";
import { useIntl } from "react-intl";
import { Link } from "react-scroll";
import { Menu, X } from "lucide-react"; // Icônes pour le hamburger et la croix

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);
  const [scrollY, setScrollY] = useState(0);
  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);
  const { locale, switchLanguage } = useLocale();
  const { formatMessage } = useIntl();

  const getLanguageLabel = (lang) => (lang === "fr" ? "🇫🇷 FR" : "🇬🇧 EN");

  useEffect(() => {
    const handleScroll = () => setScrollY(window.scrollY);
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 p-4 transition-all duration-300 bg-white">
      <div className="container mx-auto flex justify-between items-center relative px-8">
        {/* Desktop Menu */}
        <div className="hidden md:flex absolute left-1/2 transform -translate-x-1/2 space-x-6">
          <Link to="skills-slide" smooth={true} duration={500} className="text-lg font-medium hover:text-gray-400">
            {formatMessage({ id: "skills" })}
          </Link>
          <Link to="project-slide" smooth={true} duration={500} className="text-lg font-medium hover:text-gray-400">
            {formatMessage({ id: "projects" })}
          </Link>
          <Link to="contact-form" smooth={true} duration={500} className="text-lg font-medium hover:text-gray-400">
            {formatMessage({ id: "contact" })}
          </Link>
        </div>

        {/* Mobile Menu Button */}
        {!isOpen && (
          <button className="md:hidden text-black" onClick={() => setIsOpen(true)}>
            <Menu size={32} />
          </button>
        )}

        {/* Mobile Menu */}
        {isOpen && (
          <div className="md:hidden fixed top-0 left-0 w-full h-full bg-white flex flex-col items-center justify-center space-y-6 px-8">
            {/* Bouton croix en haut à gauche */}
            <button className="absolute top-4 left-4 text-black" onClick={() => setIsOpen(false)}>
              <X size={32} />
            </button>

            <Link to="skills-slide" smooth={true} duration={500} className="text-lg font-medium hover:text-gray-400" onClick={() => setIsOpen(false)}>
              {formatMessage({ id: "skills" })}
            </Link>
            <Link to="project-slide" smooth={true} duration={500} className="text-lg font-medium hover:text-gray-400" onClick={() => setIsOpen(false)}>
              {formatMessage({ id: "projects" })}
            </Link>
            <Link to="contact-form" smooth={true} duration={500} className="text-lg font-medium hover:text-gray-400" onClick={() => setIsOpen(false)}>
              {formatMessage({ id: "contact" })}
            </Link>
          </div>
        )}

        {/* Langue Switcher (Masqué si hamburger ouvert) */}
        {!isOpen && (
          <div className="ml-auto relative">
            <button
              onClick={() => setIsLangMenuOpen(!isLangMenuOpen)}
              className="focus:outline-none bg-black px-5 py-2 rounded-none text-white"
            >
              {getLanguageLabel(locale)}
            </button>

            {isLangMenuOpen && (
              <div className="absolute right-0 mt-2 w-48 bg-black text-white rounded-none shadow-lg">
                <button
                  onClick={() => {
                    switchLanguage("fr");
                    setIsLangMenuOpen(false);
                  }}
                  className="block w-full text-left px-4 py-2 hover:bg-white hover:text-black"
                >
                  🇫🇷 FR
                </button>
                <button
                  onClick={() => {
                    switchLanguage("en");
                    setIsLangMenuOpen(false);
                  }}
                  className="block w-full text-left px-4 py-2 hover:bg-white hover:text-black"
                >
                  🇬🇧 EN
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </nav>
  );
}
